package com.footballacademy.model;
import com.fasterxml.jackson.annotation.JsonIgnore; import jakarta.persistence.*;
@Entity @Table(name="match_events", indexes={@Index(name="idx_event_match", columnList="match_id"),@Index(name="idx_event_player", columnList="player_id"),@Index(name="idx_event_type", columnList="event_type"),@Index(name="idx_event_time", columnList="minute,second")})
public class MatchEvent { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="match_id") @JsonIgnore private Match match; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="player_id") @JsonIgnore private Player player; @Enumerated(EnumType.STRING) @Column(name="event_type", nullable=false) private MatchEventType eventType; private Integer minute; private Integer second; private Double xPosition; private Double yPosition; private Boolean success=true; private String pressureLevel; private Integer intensity; @Column(length=1000) private String note; public boolean isSuccessful(){return Boolean.TRUE.equals(success);} public Long getId(){return id;} public void setId(Long id){this.id=id;} public Match getMatch(){return match;} public void setMatch(Match match){this.match=match;} public Player getPlayer(){return player;} public void setPlayer(Player player){this.player=player;} public MatchEventType getEventType(){return eventType;} public void setEventType(MatchEventType eventType){this.eventType=eventType;} public Integer getMinute(){return minute;} public void setMinute(Integer minute){this.minute=minute;} public Integer getSecond(){return second;} public void setSecond(Integer second){this.second=second;} public Double getXPosition(){return xPosition;} public void setXPosition(Double xPosition){this.xPosition=xPosition;} public Double getYPosition(){return yPosition;} public void setYPosition(Double yPosition){this.yPosition=yPosition;} public Boolean getSuccess(){return success;} public void setSuccess(Boolean success){this.success=success;} public String getPressureLevel(){return pressureLevel;} public void setPressureLevel(String pressureLevel){this.pressureLevel=pressureLevel;} public Integer getIntensity(){return intensity;} public void setIntensity(Integer intensity){this.intensity=intensity;} public String getNote(){return note;} public void setNote(String note){this.note=note;} }
